#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
using namespace std;
vector<int> plusOne(vector<int>& digits) {
    for (int i = digits.size() - 1; i >= 0; i--) {
        if (digits[i] < 9) {
            digits[i]++;
            return digits;
        }
        digits[i] = 0;
    }
    digits.insert(digits.begin(), 1);
    return digits;
}
int main() {
    string line; if (!getline(cin, line)) return 0;
    for (char &c : line) if (c == '[' || c == ']' || c == ',') c = ' ';
    stringstream ss(line); int val; vector<int> d;
    while (ss >> val) d.push_back(val);
    if (d.empty() && line.find('0') != string::npos) d.push_back(0);
    vector<int> res = plusOne(d);
    cout << "[";
    for (int i = 0; i < res.size(); i++) cout << res[i] << (i == res.size() - 1 ? "" : ",");
    cout << "]" << endl;
    return 0;
}

