import java.util.*;
import java.io.*;
public class Main {
    public static int[] plusOne(int[] digits) {
        for (int i = digits.length - 1; i >= 0; i--) {
            if (digits[i] < 9) {
                digits[i]++;
                return digits;
            }
            digits[i] = 0;
        }
        int[] res = new int[digits.length + 1];
        res[0] = 1;
        return res;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine(); if (line == null) return;
        line = line.replace("[", "").replace("]", "").replace(",", " ").trim();
        if (line.isEmpty()) { System.out.println("[]"); return; }
        String[] parts = line.split("\\s+");
        int[] d = new int[parts.length];
        for (int i = 0; i < parts.length; i++) d[i] = Integer.parseInt(parts[i]);
        int[] res = plusOne(d);
        System.out.print("[");
        for (int i = 0; i < res.length; i++) System.out.print(res[i] + (i == res.length - 1 ? "" : ","));
        System.out.println("]");
    }
}

